const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Thailand';
  const faoGaul = ee.FeatureCollection('FAO/GAUL/2015/LEVEL0');
  const geometry = faoGaul.filter(ee.Filter.eq('ADM0_NAME', countryName)).geometry();

  if (!geometry) {
    console.log("Error: Could not find geometry for Thailand.");
    console.log("D");
    return;
  }

  const startDateAug = '2008-08-01';
  const endDateAug = '2008-08-31';
  const startDateFeb = '2008-02-01';
  const endDateFeb = '2008-02-29'; // Account for leap year if applicable, though 2008 was a leap year

  // Define a reasonable scale for region reduction to avoid timeouts/memory issues
  // MODIS data resolution is ~1km, so 1000m scale is appropriate.
  const scale = 1000;

  // 2. Data Acquisition & Check
  const modisFire = ee.ImageCollection('MODIS/051/MCD14ML');

  const aug2008Collection = modisFire
    .filterDate(startDateAug, endDateAug)
    .filterBounds(geometry);

  const feb2008Collection = modisFire
    .filterDate(startDateFeb, endDateFeb)
    .filterBounds(geometry);

  const augSize = await aug2008Collection.size().getInfo();
  const febSize = await feb2008Collection.size().getInfo();

  if (augSize === 0) {
    console.log("No images found for August 2008 in Thailand.");
    console.log("C1");
    return;
  }
  if (febSize === 0) {
    console.log("No images found for February 2008 in Thailand.");
    console.log("C1");
    return;
  }

  // 3. Processing: Count fire pixels
  // Define fire pixels: `fire` band value 7 indicates a detected fire
  const firePixelsAug = await aug2008Collection
    .select('fire')
    .map(image => image.eq(7).rename('fire_detection')) // Create a binary band: 1 for fire, 0 for not fire
    .sum() // Sum up all fire detections across the period. Each pixel counts as 1 if fire detected.
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    })
    .get('fire_detection')
    .getInfo();

  const firePixelsFeb = await feb2008Collection
    .select('fire')
    .map(image => image.eq(7).rename('fire_detection'))
    .sum()
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    })
    .get('fire_detection')
    .getInfo();

  // 4. Calculation & Validation
  if (firePixelsAug === null || typeof firePixelsAug === 'undefined' ||
      firePixelsFeb === null || typeof firePixelsFeb === 'undefined') {
    console.log("Calculation resulted in None/NaN for fire pixels.");
    console.log("C3");
    return;
  }

  console.log(`August 2008 Fire Detections (pixels): ${firePixelsAug}`);
  console.log(`February 2008 Fire Detections (pixels): ${firePixelsFeb}`);

  if (firePixelsAug > firePixelsFeb) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
